<script lang="ts" module>
	let query = $state<string>("");
	let mangaFeed = $state<MangaFeedResponse>();
	let authorFeed = $state<TagFeedResponse>();
	let groupFeed = $state<ScanlationGroupFeedResponse>();
</script>

<script lang="ts">
	import { API, Mutex } from "$lib";
	import { createLatestSearch } from "$platform/latest-search";
	import { toast } from "svelte-sonner";
	import * as Empty from "$lib/components/ui/empty";
	import * as InputGroup from "$lib/components/ui/input-group";
	import { isShowSearchDialog, prefs } from "$lib/stores";
	import { ArrowRightIcon, SearchIcon, X } from "@lucide/svelte";
	import { StatusCodes } from "http-status-codes";
	import { untrack } from "svelte";
	import SearchDialogMangaEntry from "./SearchDialogMangaEntry.svelte";
	import { buttonVariants } from "./ui/button";
	import Button from "./ui/button/button.svelte";
	import ScrollArea from "./ui/scroll-area/scroll-area.svelte";
	import Spinner from "./ui/spinner/spinner.svelte";

  const mutex = new Mutex();
  const latest = createLatestSearch(busy => busy ? mutex.lock() : mutex.unlock());
  const clear = () => { mangaFeed = undefined; authorFeed = undefined; groupFeed = undefined; };
  const search = (delay: number) => {
    const text = query; clear();
    if (!$isShowSearchDialog || !text.length) { latest.invalidate(); return; }
    latest.schedule(delay, async signal => {
      const mq = new URLSearchParams(); prefs.applyMangaPreferences(mq); mq.set("title", text); mq.set("sort", "relevance"); mq.set("limit", "5");
      const aq = new URLSearchParams(); aq.set("name", text); aq.set("limit", "5");
      const gq = new URLSearchParams(); gq.set("name", text); gq.set("limit", "5");
      const responses = await Promise.all([API.Manga.Search(mq, signal), API.Author.Search(aq, signal), API.Group.Search(gq, signal)]);
      if (responses.some(res => res?.status !== StatusCodes.OK || !res.body)) throw Error("Search could not be completed. Try the current query again.");
      return responses;
    }, responses => {
      if (!$isShowSearchDialog || query !== text) return;
      [mangaFeed, authorFeed, groupFeed] = responses.map(res => res!.body) as [MangaFeedResponse, TagFeedResponse, ScanlationGroupFeedResponse];
    }, cause => toast.error("Search failed", { description: cause instanceof Error ? cause.message : "The current search could not be loaded." }));
  };
  $effect.pre(() => { const open = $isShowSearchDialog; untrack(() => { latest.invalidate(); clear(); if (open && query.length) search(0); }); });
  const onInput = () => search(500);
  const onSubmit = (event?: SubmitEvent) => { event?.preventDefault(); search(0); };
</script>

<div class="flex shrink-0 items-center gap-1">
	<InputGroup.Root class="!border-border rounded-none !border-x-0 !border-t-0 py-5 !ring-0 !ring-transparent">
		<InputGroup.Input
			class="w-0 flex-auto truncate"
			bind:value={query}
			placeholder="Search titles, authors, or groups..."
			autocomplete="off"
			oninput={onInput}
			onsubmit={onSubmit}
		/>
		<InputGroup.Addon>
			{#if $mutex}
				<Spinner />
			{:else}
				<SearchIcon />
			{/if}
		</InputGroup.Addon>
		<InputGroup.Addon align="inline-end">
			<Button class="-mr-0.75" type="button" variant="ghost" size="icon" onclick={() => ($isShowSearchDialog = false)}>
				<X class="size-5" />
			</Button>
		</InputGroup.Addon>
	</InputGroup.Root>
</div>
<div class="flex h-full flex-auto overflow-hidden p-2">
	<ScrollArea class="w-full flex-auto" scrollbarYClasses="hidden">
		{#if $mutex}
			<Empty.Root>
				<Empty.Header>
					<Empty.Description>Searching...</Empty.Description>
				</Empty.Header>
			</Empty.Root>
		{:else if mangaFeed || authorFeed || groupFeed}
			{#if mangaFeed?.total || authorFeed?.total || groupFeed?.total}
				<div class="space-y-3">
					{#if mangaFeed?.total}
						<section>
							<header class="mb-1 flex items-center">
								<h2 class="w-0 flex-auto font-medium">Titles</h2>
								{#if mangaFeed.total > mangaFeed.limit}
									<div class="shrink-0">
										<a
											class={buttonVariants({
												variant: "ghost",
												class: "hover:!bg-input/50 size-6"
											})}
											href={`/search${new URLSearchParams({ title: query, sort: "relevance" }).toString()}`}
										>
											<ArrowRightIcon class="size-5" />
										</a>
									</div>
								{/if}
							</header>
							<div class="space-y-1">
								{#each mangaFeed.data as manga}
									<SearchDialogMangaEntry {manga} />
								{/each}
							</div>
						</section>
					{/if}

					{#if groupFeed?.total}
						<section>
							<header class="mb-1 flex items-center">
								<h2 class="w-0 flex-auto font-medium">Scanlation Groups</h2>
								{#if groupFeed.total > groupFeed.limit}
									<div class="shrink-0">
										<a
											class={buttonVariants({
												variant: "ghost",
												class: "hover:!bg-input/50 size-6"
											})}
											href={`/groups${new URLSearchParams({ name: query }).toString()}`}
										>
											<ArrowRightIcon class="size-5" />
										</a>
									</div>
								{/if}
							</header>
							<div class="space-y-1">
								{#each groupFeed.data as group}
									<article>
										<a
											class={buttonVariants({
												variant: "outline",
												class: "w-full justify-start border-none"
											})}
											href="/group/{group.id}"
											title={group.name}
										>
											<span class="truncate">{group.name}</span>
										</a>
									</article>
								{/each}
							</div>
						</section>
					{/if}

					{#if authorFeed?.total}
						<section>
							<header class="mb-1 flex items-center">
								<h2 class="w-0 flex-auto font-medium">Authors</h2>
							</header>
							<div class="space-y-1">
								{#each authorFeed.data as author}
									<article>
										<a
											class={buttonVariants({
												variant: "outline",
												class: "w-full justify-start border-none"
											})}
											href="/author/{author.id}"
											title={author.name}
										>
											<span class="truncate">{author.name}</span>
										</a>
									</article>
								{/each}
							</div>
						</section>
					{/if}
				</div>
			{:else}
				<Empty.Root>
					<Empty.Header>
						<Empty.Description>No results found</Empty.Description>
					</Empty.Header>
				</Empty.Root>
			{/if}
		{:else}
			<Empty.Root>
				<Empty.Header>
					<Empty.Description>Type to search…</Empty.Description>
				</Empty.Header>
			</Empty.Root>
		{/if}
	</ScrollArea>
</div>
